changeSet.sql:

			drop table if exists po_menu;

			create table po_menu (
			po_id              bigint primary key,
 			json_menu		   text
 			);
			 alter table po_menu add FOREIGN KEY (po_id) REFERENCES po_portalobject(id) ON DELETE CASCADE;

create table if not exists wf_form_data (
	id					bigint primary key,
	activity_id			bigint references wf_activity(id) on delete cascade,
	form_id				bigint references kb_form(id) on delete restrict,
	data				text
);

update kb_classifier set workflow_status=true where lower(name)='status';
update kb_classifier set workflow_status=false where lower(name)!='status';
update kb_classifier set is_content_type=false;
update kb_classifier set is_content_type=true where lower(name)='document type' or lower(name)='file type' or lower(name)='type';

			CREATE TABLE USER_EXTERNAL_LOGIN_PLATFORM (
				ID              		bigint primary key,
 				USERPROFILE_ID 			bigint not null,
 				PLATFORM_ID				int not null,
 				USER_PLATFORM_ID_TYPE   int not null,
 				USER_PLATFORM_ID    	text not null,
				ENABLED    				boolean  not null
 			);
 			 alter table USER_EXTERNAL_LOGIN_PLATFORM add FOREIGN KEY (USERPROFILE_ID) REFERENCES USERPROFILE(id) ON DELETE CASCADE;

			create table payment_mercadopago
            (
				id bigint primary key,
				preference_id text,
				payment_id text
			);

			ALTER TABLE payment_mercadopago ADD CONSTRAINT fk_payment_ml_payment FOREIGN KEY (id) REFERENCES payment(id);

 				alter table po_site add column if not exists isbuildable boolean default true;
 			 	alter table po_page_section  add column if not exists isbuildable boolean default true;
				alter table po_area  add column if not exists isbuildable boolean default true;


	alter table po_page          add column if not exists css character varying(256);
 	alter table po_page_section  add column if not exists css character varying(256);
 	alter table po_area 		 add column if not exists css character varying(256);
 	alter table po_block	     add column if not exists css character varying(256);


CREATE TABLE  if not exists po_viewbkiql  (
view_id  bigint not null primary key references po_viewbk(po_id) ON DELETE CASCADE,  
iql   character varying(1024)  );


			drop table if exists po_block_listview;

			CREATE TABLE if not exists po_block_listview (
				po_id bigint primary key references po_block(po_id)
 			);

drop table if exists po_block_site_list;
drop table if exists po_block_text;
drop table if exists po_block_x;
drop table if exists po_block_image_viewer;
drop table if exists po_block_select_list;
drop table if exists po_block_site_components;
drop table if exists po_block_selector;

alter table po_viewbk drop constraint if exists viewbk_block_fk;
alter table po_viewbk add constraint viewbk_block_fk  foreign key (block_id)  references po_block(po_id) on delete cascade;

alter table po_viewbkblock drop constraint if exists viewbkblock_site_fk;

alter table po_viewbkblock drop constraint if exists viewbk_block_fk;
alter table po_viewbkblock  add constraint viewbk_block_fk  foreign key (block_id)  references po_block(po_id) on delete cascade;

drop table if exists  po_diagrammable_block cascade;
drop table if exists  po_diagrammable_area;
drop table if exists  po_diagrammable_page cascade;
drop table if exists  po_diagrammable_site cascade;

 alter table po_viewbk drop column if exists position;
 alter table po_viewbk drop column if exists list_position;
 alter table po_viewbk add column list_position integer default 0;

alter table po_viewbk drop column if exists  title;
alter table po_viewbk drop column if exists subtitle;
alter table po_viewbk drop column if exists  description;
alter table po_viewbk drop column if exists  tagline;
alter table po_viewbk drop column if exists  vtext;
alter table po_viewbk drop column if exists  css;

alter table po_viewbk drop column if exists  abstract;
alter table po_viewbk drop column if exists  metadata;

alter table po_viewbk add column subtitle character varying(256);
alter table po_viewbk add column tagline character varying(256);
alter table po_viewbk add column css  character varying(256);

alter table po_viewbk add column vtext text;


			drop table if exists po_block_generic_content_list;

			CREATE TABLE if not exists po_block_generic_content_list (
				po_id bigint primary key references po_block(po_id) on delete cascade
 			);


alter table po_block add column if not exists isPayloadEditor boolean default false;
alter table po_area  add column if not exists isPayloadEditor boolean default false;
alter table po_page  add column if not exists isPayloadEditor boolean default false;
alter table po_page_section add column if not exists isPayloadEditor boolean default false;
alter table po_site add column if not exists isPayloadEditor boolean default false;
